// 1. Code Block Copy Buttons
// Copy buttons are generated by js. This is intentional design. If
// they were pre-parsed, when you remove this file they would still
// be there without any functionality. It could be fixed by adding extra option
// in init, but this may result in extra refactoring for no practical performance boost.
function initCodeBlocks() {
    document.querySelectorAll('pre').forEach((block) => {
        if (getComputedStyle(block).position === 'static') {
            block.style.position = 'relative';
        }

        const copyButton = document.createElement('button');
        copyButton.type = 'button';
        const copyIcon = `<svg fill="currentColor" aria-hidden="true" height="16"
viewBox="0 0 16 16" version="1.1" width="16"
data-view-component="true">
<path
d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z">
</path>
</svg>`.replaceAll("\n", " ");
        const confirmIcon = `<svg fill="currentColor"
aria-hidden="true"
height="16" viewBox="0 0 16 16"
version="1.1" width="16"
data-view-component="true">
<path d = "M13.78 4.22a.75.75 0 0 1 0 1.06l-7.25 7.25a.75.75 0 0 1-1.06 0L2.22 9.28a.751.751 0 0 1 .018-1.042.751.751 0 0 1 1.042-.018L6 10.94l6.72-6.72a.75.75 0 0 1 1.06 0Z" ></path>
</svg>`.replaceAll("\n", " ");
        copyButton.innerHTML = copyIcon;
        Object.assign(copyButton.style, {
            position: 'absolute',
            top: '8px',
            right: '8px',
            padding: '4px 8px',
            fontSize: '12px',
            fontFamily: 'sans-serif',
            background: '#2d2d2d',
            color: '#ffffff',
            border: '1px solid #444',
            borderRadius: 'var(--radius-sm)',
            cursor: 'pointer',
            zIndex: '10',
            transition: 'background 0.2s ease'
        });

        copyButton.addEventListener('mouseenter', () => copyButton.style.background = '#444');
        copyButton.addEventListener('mouseleave', () => copyButton.style.background = '#2d2d2d');

        copyButton.addEventListener('click', async () => {
            const codeElement = block.querySelector('code');
            const textToCopy = codeElement ? codeElement.innerText : block.innerText;
            try {
                await navigator.clipboard.writeText(textToCopy);
                copyButton.innerHTML = confirmIcon;
            } catch (err) {
                console.error('Failed to copy text: ', err);
                copyButton.innerText = 'Error';
            } finally {
                setTimeout(() => copyButton.innerHTML = copyIcon, 2000);
            }
        });

        block.appendChild(copyButton);
    });
}
